1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { requireArea } from "./rbac";
7	import { GAME_FAMILIES, type GameFamily } from "./games";
8	
9	/**
10	 * Update Announcements — service-specific release notes pushed to customers.
11	 *
12	 * Admin creates a DRAFT, then explicitly publishes it (the approval gate).
13	 * Customers see a popup on first login after publish and a persistent
14	 * "What's New" feed. `serviceTypes` scopes visibility: a user only sees
15	 * announcements for services they actually have; empty = everyone.
16	 *
17	 * Admin actions are area-gated ("platform"). Customer actions self-auth via
18	 * `requireUser()` and only ever touch that user's own rows.
19	 */
20	
21	/** Widened from the original 4 to match the concept's filter row and every
22	 *  real product area — DOMAINS/BILLING/PLATFORM were previously unrepresentable
23	 *  (an admin authoring a domains or platform-wide update had nowhere to put it
24	 *  but the general "empty = everyone" bucket). */
25	const SERVICE_TYPES = ["GAME", "VPS", "HOSTING", "DOMAINS", "MAIL", "BILLING", "PLATFORM"] as const;
26	export type ServiceType = (typeof SERVICE_TYPES)[number];
27	
28	/** What kind of change an update is — author-set, drives the What's New
29	 *  page's icon/tone/filter. Never inferred from the title. */
30	const KINDS = ["FEATURE", "IMPROVEMENT", "BUGFIX"] as const;
31	export type AnnouncementKind = (typeof KINDS)[number];
32	
33	// ---------- Admin ----------
34	
35	export async function listAnnouncements() {
36	  await requireArea("platform");
37	  return db.updateAnnouncement.findMany({
38	    orderBy: { createdAt: "desc" },
39	    take: 200,
40	    include: { _count: { select: { seenBy: true } } },
41	  });
42	}
43	
44	export async function createAnnouncement(input: {
45	  title: string;
46	  body: string;
47	  kind?: string;
48	  serviceTypes: string[];
49	  gameFamilies?: string[];
50	  screenshotUrl?: string | null;
51	}): Promise<{ error?: string; ok?: boolean }> {
52	  await requireArea("platform");
53	  const title = String(input.title ?? "").trim();
54	  if (!title) return { error: "Enter a title." };
55	  const body = String(input.body ?? "").trim();
56	  if (!body) return { error: "Enter a body." };
57	
58	  const kind = (KINDS as readonly string[]).includes(input.kind ?? "") ? (input.kind as AnnouncementKind) : "FEATURE";
59	
60	  // Validate service types — only allow known values.
61	  const serviceTypes = (input.serviceTypes ?? []).filter((t) =>
62	    (SERVICE_TYPES as readonly string[]).includes(t),
63	  );
64	
65	  // Game families only make sense when the update is GAME-scoped. Validate
66	  // against the real game family list so a typo can never silently no-op.
67	  const gameFamilies = serviceTypes.includes("GAME")
68	    ? (input.gameFamilies ?? []).filter((g) => (GAME_FAMILIES as readonly string[]).includes(g))
69	    : [];
70	
71	  // Screenshot must be a relative path, not an external URL.
72	  let screenshotUrl: string | null = null;
73	  if (input.screenshotUrl) {
74	    const u = input.screenshotUrl.trim();
75	    if (u && !u.startsWith("/")) return { error: "Screenshot must be a relative path (e.g. /uploads/announcements/img.png)." };
76	    screenshotUrl = u || null;
77	  }
78	
79	  await db.updateAnnouncement.create({
80	    data: {
81	      title: title.slice(0, 200),
82	      body: body.slice(0, 10_000),
83	      kind,
84	      serviceTypes,
85	      gameFamilies,
86	      screenshotUrl,
87	      status: "DRAFT",
88	    },
89	  });
90	  revalidatePath("/admin/announcements");
91	  return { ok: true };
92	}
93	
94	export async function publishAnnouncement(id: string): Promise<void> {
95	  await requireArea("platform");
96	  await db.updateAnnouncement.update({
97	    where: { id },
98	    data: { status: "PUBLISHED", publishedAt: new Date() },
99	  });
100	  revalidatePath("/admin/announcements");
101	}
102	
103	export async function unpublishAnnouncement(id: string): Promise<void> {
104	  await requireArea("platform");
105	  await db.updateAnnouncement.update({
106	    where: { id },
107	    data: { status: "DRAFT" },
108	  });
109	  revalidatePath("/admin/announcements");
110	}
111	
112	export async function deleteAnnouncement(id: string): Promise<void> {
113	  await requireArea("platform");
114	  await db.updateAnnouncement.delete({ where: { id } }).catch(() => undefined);
115	  revalidatePath("/admin/announcements");
116	}
117	
118	// ---------- Customer ----------
119	
120	/** Determine which service types the current user has active services for.
121	 *  BILLING and PLATFORM are unconditional — every account has a wallet, and a
122	 *  platform-wide change (a new region, an infra migration) affects everyone
123	 *  regardless of which products they've bought. */
124	async function getUserServiceTypes(userId: string): Promise<string[]> {
125	  const [servers, hosting, domain] = await Promise.all([
126	    db.server.findFirst({ where: { userId } }),
127	    db.hostingAccount.findFirst({ where: { userId } }),
128	    db.domain.findFirst({ where: { userId } }),
129	  ]);
130	  const types: string[] = ["BILLING", "PLATFORM"];
131	  if (servers) {
132	    const hasGame = await db.server.findFirst({
133	      where: { userId, gamePlanId: { not: null } },
134	    });
135	    if (hasGame) types.push("GAME");
136	    const hasVps = await db.server.findFirst({
137	      where: { userId, gamePlanId: null },
138	    });
139	    if (hasVps) types.push("VPS");
140	  }
141	  if (hosting) types.push("HOSTING");
142	  // MAIL: anyone with a hosting account potentially has mail; we keep it
143	  // simple and include MAIL for hosting customers too.
144	  if (hosting) types.push("MAIL");
145	  if (domain) types.push("DOMAINS");
146	  return types;
147	}
148	
149	/**
150	 * PUBLISHED announcements the current user hasn't seen, filtered by service
151	 * types matching their actual services. An announcement with empty
152	 * serviceTypes[] is shown to everyone.
153	 */
154	export async function getUnseenAnnouncements() {
155	  const user = await requireUser();
156	  const userServices = await getUserServiceTypes(user.id);
157	
158	  const announcements = await db.updateAnnouncement.findMany({
159	    where: {
160	      status: "PUBLISHED",
161	      seenBy: { none: { userId: user.id } },
162	    },
163	    orderBy: { publishedAt: "desc" },
164	  });
165	
166	  // Filter by service type: show if announcement has no serviceTypes (global)
167	  // or if at least one of the user's service types matches.
168	  return announcements.filter(
169	    (a) =>
170	      a.serviceTypes.length === 0 ||
171	      a.serviceTypes.some((t) => userServices.includes(t)),
172	  );
173	}
174	
175	/** Mark an announcement as seen by the current user. Upserts to stay idempotent. */
176	export async function markAnnouncementSeen(announcementId: string): Promise<void> {
177	  const user = await requireUser();
178	  await db.userAnnouncementSeen.upsert({
179	    where: {
180	      userId_announcementId: { userId: user.id, announcementId },
181	    },
182	    create: { userId: user.id, announcementId },
183	    update: {},
184	  });
185	}
186	
187	export type WhatsNewEntry = {
188	  id: string;
189	  title: string;
190	  body: string;
191	  kind: AnnouncementKind;
192	  serviceTypes: string[];
193	  gameFamilies: string[];
194	  screenshotUrl: string | null;
195	  publishedAt: string; // ISO string for serialization
196	  seen: boolean;
197	};
198	
199	/**
200	 * All PUBLISHED announcements, optionally filtered by service type, ordered
201	 * by publishedAt desc, with a `seen` boolean flag for the current user.
202	 */
203	export async function getWhatsNew(
204	  serviceFilter?: string,
205	): Promise<WhatsNewEntry[]> {
206	  const user = await requireUser();
207	
208	  const where: Record<string, unknown> = { status: "PUBLISHED" };
209	  if (serviceFilter && (SERVICE_TYPES as readonly string[]).includes(serviceFilter)) {
210	    where.serviceTypes = { has: serviceFilter };
211	  }
212	
213	  const announcements = await db.updateAnnouncement.findMany({
214	    where,
215	    orderBy: { publishedAt: "desc" },
216	    include: {
217	      seenBy: {
218	        where: { userId: user.id },
219	        take: 1,
220	      },
221	    },
222	  });
223	
224	  return announcements.map((a) => ({
225	    id: a.id,
226	    title: a.title,
227	    body: a.body,
228	    kind: ((KINDS as readonly string[]).includes(a.kind) ? a.kind : "FEATURE") as AnnouncementKind,
229	    serviceTypes: a.serviceTypes,
230	    gameFamilies: a.gameFamilies,
231	    screenshotUrl: a.screenshotUrl,
232	    publishedAt: (a.publishedAt ?? a.createdAt).toISOString(),
233	    seen: a.seenBy.length > 0,
234	  }));
235	}
236	
237	/**
238	 * Real counts behind the What's New page's stats card — every number here is
239	 * a straight aggregate over PUBLISHED rows, never estimated. "Major releases"
240	 * and "Fixes & improvements" are just `kind` grouped two ways, not a second
241	 * concept: a FEATURE is the "major" half, IMPROVEMENT + BUGFIX are the other.
242	 */
243	export async function getWhatsNewStats(): Promise<{
244	  total: number; newThisMonth: number; majorReleases: number; fixesAndImprovements: number;
245	}> {
246	  const monthStart = new Date();
247	  monthStart.setDate(1);
248	  monthStart.setHours(0, 0, 0, 0);
249	  const base = { status: "PUBLISHED" } as const;
250	  const [total, newThisMonth, majorReleases, fixesAndImprovements] = await Promise.all([
251	    db.updateAnnouncement.count({ where: base }),
252	    db.updateAnnouncement.count({ where: { ...base, publishedAt: { gte: monthStart } } }),
253	    db.updateAnnouncement.count({ where: { ...base, kind: "FEATURE" } }),
254	    db.updateAnnouncement.count({ where: { ...base, kind: { in: ["IMPROVEMENT", "BUGFIX"] } } }),
255	  ]);
256	  return { total, newThisMonth, majorReleases, fixesAndImprovements };
257	}
