202	function AnnouncementCard({ entry, onSeen }: { entry: WhatsNewEntry; onSeen: (id: string) => void }) {
203	  const ref = useRef<HTMLDivElement>(null);
204	  const marked = useRef(false);
205	  const [, startTransition] = useTransition();
206	
207	  useEffect(() => {
208	    if (entry.seen || marked.current) return;
209	    const el = ref.current;
210	    if (!el) return;
211	    const observer = new IntersectionObserver(([e]) => {
212	      if (e.isIntersecting && !marked.current) {
213	        marked.current = true;
214	        const timer = setTimeout(() => {
215	          onSeen(entry.id);
216	          startTransition(() => { markAnnouncementSeen(entry.id).catch(() => {}); });
217	        }, 2000);
218	        observer.disconnect();
219	        return () => clearTimeout(timer);
220	      }
221	    }, { threshold: 0.5 });
222	    observer.observe(el);
223	    return () => observer.disconnect();
224	    // eslint-disable-next-line react-hooks/exhaustive-deps
225	  }, [entry.id, entry.seen]);
226	
227	  const formatted = new Date(entry.publishedAt).toLocaleDateString(undefined, {
228	    month: "short", day: "numeric", year: "numeric",
229	  });
230	  const leadService = entry.serviceTypes[0] ? SERVICE_META[entry.serviceTypes[0]] : null;
