241	            <div className="flex flex-wrap items-center gap-2">
242	              <span suppressHydrationWarning className="text-[11.5px] text-tx-faint">{formatted}</span>
243	              {!entry.seen && <span className="badge badge-mint text-[10px]">New</span>}
244	              <span className={kindMeta.badgeClass + " text-[10px]"}>{kindMeta.label}</span>
245	              {entry.serviceTypes.length > 0 && (
246	                <div className="ml-auto flex flex-wrap gap-1.5">
247	                  {entry.serviceTypes.map((t) => <ServiceTag key={t} type={t} />)}
248	                </div>
249	              )}
250	            </div>
251	
252	            <h3 className="mt-1.5 text-[15.5px] font-extrabold text-white">{entry.title}</h3>
253	
254	            {entry.gameFamilies.length > 0 && (
255	              <div className="mt-3">
256	                {entry.gameFamilies.length > 1 && (
257	                  <p className="mb-2 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">
258	                    Games covered in this update
259	                  </p>
260	                )}
261	                <div className={"grid gap-2 " + (entry.gameFamilies.length === 1 ? "grid-cols-3 sm:grid-cols-4" : "grid-cols-4 sm:grid-cols-6")}>
262	                  {entry.gameFamilies.map((g) => (
263	                    // nx-dark-island: GameCoverTile always draws photographic box
264	                    // art (or a per-game gradient fallback), never the themed page
265	                    // surface, so the caption below it stays on a literal black
266	                    // strip in both themes — same reasoning ServiceCard.tsx's
267	                    // preview well uses. Without it, light mode's tx-body token
268	                    // flips to dark ink, making every game name unreadable against
269	                    // its own bg-black/40 caption.
270	                    <div key={g} className="nx-dark-island overflow-hidden rounded-[10px] border border-rim-hi">
271	                      <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
272	                      <p className="trunc bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-tx-body">
273	                        {GAME_DISPLAY[g as GameFamily]?.name ?? g}
274	                      </p>
275	                    </div>
276	                  ))}
277	                </div>
278	              </div>
279	            )}
280	
281	            <div className="mt-2.5 text-[13px] leading-[1.6] text-tx-mute" dangerouslySetInnerHTML={{ __html: renderMarkdown(entry.body) }} />
282	
283	            {entry.screenshotUrl && (
284	              <img src={entry.screenshotUrl} alt={`Screenshot for ${entry.title}`}
285	                   className="mt-4 w-full rounded-[12px] border border-rim-hi shadow-lg shadow-black/20" loading="lazy" />
286	            )}
287	          </div>
288	        </div>
