100	/** A Markdown body field with a formatting toolbar + Write/Preview tabs. */
101	function MarkdownField({
102	  value,
103	  onChange,
104	  placeholder,
105	}: {
106	  value: string;
107	  onChange: (v: string) => void;
108	  placeholder?: string;
109	}) {
110	  const [tab, setTab] = useState<"write" | "preview">("write");
111	  const ref = useRef<HTMLTextAreaElement>(null);
112	
113	  function runTool(tool: ToolAction) {
114	    const el = ref.current;
115	    if (!el) return;
116	    const start = el.selectionStart ?? value.length;
117	    const end = el.selectionEnd ?? value.length;
118	    const selected = value.slice(start, end);
119	    const { text, cursorOffset } = tool.apply(selected);
120	    const next = value.slice(0, start) + text + value.slice(end);
121	    onChange(next);
122	    // Restore focus + a sensible cursor position after the DOM updates.
123	    requestAnimationFrame(() => {
124	      el.focus();
125	      const pos = start + text.length + (cursorOffset ?? 0);
126	      el.setSelectionRange(pos, pos);
127	    });
128	  }
129	
130	  return (
131	    <div className="overflow-hidden rounded-xl border border-white/[0.08]">
132	      <div className="flex items-center justify-between border-b border-white/[0.06] bg-white/[0.02] px-2 py-1.5">
133	        <div className="flex flex-wrap gap-0.5">
134	          {TOOLS.map((tool) => (
135	            <button
136	              key={tool.label}
137	              type="button"
138	              title={tool.label}
139	              onClick={() => runTool(tool)}
140	              disabled={tab === "preview"}
141	              className="rounded-md px-2 py-1 text-xs font-medium text-slate-300 transition-colors hover:bg-white/[0.06] hover:text-white disabled:opacity-30"
142	            >
143	              {tool.icon}
144	            </button>
145	          ))}
146	        </div>
147	        <div className="flex gap-1">
148	          <button
149	            type="button"
150	            onClick={() => setTab("write")}
151	            className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
152	              tab === "write" ? "bg-brand-500/20 text-brand-300" : "text-slate-500 hover:text-white"
153	            }`}
154	          >
155	            Write
156	          </button>
157	          <button
158	            type="button"
159	            onClick={() => setTab("preview")}
160	            className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
161	              tab === "preview" ? "bg-brand-500/20 text-brand-300" : "text-slate-500 hover:text-white"
162	            }`}
163	          >
164	            Preview
165	          </button>
166	        </div>
167	      </div>
168	      {tab === "write" ? (
169	        <textarea
170	          ref={ref}
171	          className="w-full resize-y border-0 bg-transparent px-3 py-2.5 font-mono text-sm text-white placeholder:text-slate-600 focus:outline-none"
172	          rows={8}
173	          placeholder={placeholder}
174	          value={value}
175	          onChange={(e) => onChange(e.target.value)}
176	          maxLength={10000}
177	        />
178	      ) : (
179	        <div className="min-h-[176px] px-3 py-2.5">
180	          {value.trim() ? (
181	            <div dangerouslySetInnerHTML={{ __html: renderMarkdown(value) }} />
182	          ) : (
183	            <p className="text-sm text-slate-600">Nothing to preview yet.</p>
184	          )}
185	        </div>
186	      )}
187	    </div>
188	  );
189	}
