23	/**
24	 * Shows unseen update announcements as a modal popup, one at a time.
25	 * Mounted inside the dashboard layout so it only fires for authenticated users.
26	 * Uses createPortal to escape any transformed ancestors (same fix as
27	 * HeardAboutUsPrompt.tsx).
28	 */
29	export function AnnouncementPopup() {
30	  const [queue, setQueue] = useState<Announcement[]>([]);
31	  const [loaded, setLoaded] = useState(false);
32	  const [, startTransition] = useTransition();
33	
34	  useEffect(() => {
35	    let cancelled = false;
36	    getUnseenAnnouncements()
37	      .then((items) => {
38	        if (!cancelled) {
39	          setQueue(items);
40	          setLoaded(true);
41	        }
42	      })
43	      .catch(() => {
44	        // Soft-fail: never block the portal over a failed announcement fetch.
45	        if (!cancelled) setLoaded(true);
46	      });
47	    return () => {
48	      cancelled = true;
49	    };
50	  }, []);
51	
52	  const dismiss = useCallback(() => {
53	    const current = queue[0];
54	    if (!current) return;
55	    // Remove from queue optimistically.
56	    setQueue((prev) => prev.slice(1));
57	    // Persist the seen record in the background.
58	    startTransition(async () => {
59	      try {
60	        await markAnnouncementSeen(current.id);
61	      } catch {
62	        /* best-effort */
63	      }
64	    });
65	  }, [queue]);
66	
67	  // Nothing to show (not loaded, or no unseen announcements).
68	  if (!loaded || queue.length === 0) return null;
69	  if (typeof document === "undefined") return null;
70	
71	  const current = queue[0];
72	
73	  return createPortal(
74	    <div
75	      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
76	      role="dialog"
77	      aria-modal="true"
78	      aria-labelledby="announcement-title"
79	      onClick={dismiss}
80	    >
81	      <div
82	        className="card w-full max-w-2xl overflow-hidden motion-safe:animate-panel-in"
83	        onClick={(e) => e.stopPropagation()}
84	      >
85	        {/* Header */}
86	        <div className="border-b border-white/[0.06] bg-gradient-to-r from-brand-500/10 to-accent-blue/10 px-6 py-4">
87	          <div className="flex items-center gap-2">
88	            <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-500/20 text-brand-300">
89	              <svg
90	                width="14"
91	                height="14"
92	                viewBox="0 0 24 24"
93	                fill="none"
94	                stroke="currentColor"
95	                strokeWidth="2"
96	                strokeLinecap="round"
97	                strokeLinejoin="round"
98	              >
99	                <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
100	              </svg>
101	            </span>
102	            <span className="text-xs font-medium uppercase tracking-wider text-brand-300">
103	              What&apos;s new
104	            </span>
105	          </div>
106	          <h2
107	            id="announcement-title"
108	            className="mt-2 text-lg font-bold tracking-tight text-white"
109	          >
110	            {current.title}
111	          </h2>
112	          {current.serviceTypes.length > 0 && (
113	            <div className="mt-1.5 flex gap-1.5">
114	              {current.serviceTypes.map((t) => (
115	                <span
116	                  key={t}
117	                  className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
118	                >
119	                  {t}
120	                </span>
121	              ))}
122	            </div>
123	          )}
124	        </div>
125	
126	        {/* Body */}
127	        <div className="max-h-[60vh] overflow-y-auto px-6 py-5">
128	          {current.gameFamilies.length > 0 && (
129	            <div className="mb-4">
130	              <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
131	                {current.gameFamilies.length > 1 ? "Games covered in this update" : "Game"}
132	              </p>
133	              <div className={`grid gap-2 ${current.gameFamilies.length === 1 ? "grid-cols-3" : "grid-cols-4 sm:grid-cols-5"}`}>
134	                {current.gameFamilies.map((g) => (
135	                  <div key={g} className="overflow-hidden rounded-lg border border-white/10">
136	                    <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
137	                    <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
138	                      {GAME_DISPLAY[g as GameFamily]?.name ?? g}
139	                    </p>
140	                  </div>
141	                ))}
142	              </div>
143	            </div>
144	          )}
145	          <div
146	            dangerouslySetInnerHTML={{ __html: renderMarkdown(current.body) }}
147	          />
148	          {current.screenshotUrl && (
149	            <div className="mt-4">
150	              {/* eslint-disable-next-line @next/next/no-img-element */}
151	              <img
152	                src={current.screenshotUrl}
153	                alt={`Screenshot for ${current.title}`}
154	                className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
155	                loading="lazy"
156	              />
157	            </div>
158	          )}
159	        </div>
160	
161	        {/* Footer */}
162	        <div className="flex items-center justify-between border-t border-white/[0.06] px-6 py-4">
163	          <span className="text-xs text-slate-500">
164	            {queue.length > 1
165	              ? `1 of ${queue.length} updates`
166	              : ""}
167	          </span>
168	          <button className="btn-primary" onClick={dismiss}>
169	            {queue.length > 1 ? "Next" : "Got it"}
170	          </button>
171	        </div>
172	      </div>
173	    </div>,
174	    document.body,
175	  );
176	}
